const now=Date.now();const run_id='RUN-REALISTIC-CONNECTED-'+now;
const seed=(now.toString(16)+Math.random().toString(16).slice(2)).replace(/[^a-f0-9]/g,'');const parent_trace_id=(seed+seed+seed).slice(0,32).padEnd(32,'0');
return [{json:{run_id,parent_trace_id,orchestration_context:{run_id,parent_trace_id,orchestrator_version:'realistic-connected-v0.1',dynamic_stage_handoffs:true},started_at:new Date().toISOString()}}];

const x = $input.first().json;
const validation = x.validation ?? {};

const isPresent = (value) => value !== undefined && value !== null && value !== '';
const firstPresent = (...values) => values.find(isPresent);
const numberOrOriginal = (value) => {
  if (!isPresent(value)) return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : value;
};
const passLike = (value) => {
  if (value === true) return true;
  if (typeof value === 'string') return ['pass', 'passed'].includes(value.toLowerCase());
  const numeric = Number(value);
  return Number.isFinite(numeric) && numeric >= 1;
};

const unsupportedClaims = firstPresent(validation.unsupported_claims, x.unsupported_claims);
const orphanChecks = Object.entries(validation).filter(([key]) => key.startsWith('orphan_'));
const deterministicPresent = x.execution_status !== undefined && isPresent(unsupportedClaims);
const deterministicPass = deterministicPresent
  && x.execution_status === 'passed'
  && Number(unsupportedClaims) === 0
  && orphanChecks.every(([, value]) => Number(value) === 0);

const codeRaw = firstPresent(
  x.evaluation_scores?.langfuse_code,
  x.langfuse_scores?.code,
  x.langfuse?.code_score,
);
const faithfulnessRaw = firstPresent(
  x.evaluation_scores?.llm_faithfulness,
  x.langfuse_scores?.faithfulness,
  x.langfuse?.faithfulness,
);
const hallucinationRaw = firstPresent(
  x.evaluation_scores?.llm_hallucination,
  x.langfuse_scores?.hallucination,
  x.langfuse?.hallucination,
);

const status = (present, passed) => present ? (passed ? 'pass' : 'fail') : 'missing';
const codePresent = isPresent(codeRaw);
const faithfulnessPresent = isPresent(faithfulnessRaw);
const hallucinationPresent = isPresent(hallucinationRaw);
const faithfulnessValue = numberOrOriginal(faithfulnessRaw);
const hallucinationValue = numberOrOriginal(hallucinationRaw);

const layers = {
  deterministic_controls: {
    status: status(deterministicPresent, deterministicPass),
    observed: {
      execution_status: x.execution_status ?? null,
      unsupported_claims: isPresent(unsupportedClaims) ? Number(unsupportedClaims) : null,
      orphan_checks: Object.fromEntries(orphanChecks),
    },
  },
  langfuse_code: {
    status: status(codePresent, codePresent && passLike(codeRaw)),
    observed: numberOrOriginal(codeRaw),
  },
  llm_faithfulness: {
    status: status(
      faithfulnessPresent,
      faithfulnessPresent && typeof faithfulnessValue === 'number' && faithfulnessValue >= 0.90,
    ),
    observed: faithfulnessValue,
  },
  llm_hallucination: {
    status: status(
      hallucinationPresent,
      hallucinationPresent && typeof hallucinationValue === 'number' && hallucinationValue <= 0.10,
    ),
    observed: hallucinationValue,
  },
};

const layerEntries = Object.entries(layers);
const failed = layerEntries.filter(([, layer]) => layer.status === 'fail').map(([name]) => name);
const missing = layerEntries.filter(([, layer]) => layer.status === 'missing').map(([name]) => name);
const wouldRelease = layerEntries.every(([, layer]) => layer.status === 'pass');
const enforcementEnabled = true; // Enabled only in this separate, owner-approved enforcement candidate.
const releaseAuthorized = !enforcementEnabled || wouldRelease;
const reasons = [
  ...failed.map((name) => `${name}:fail`),
  ...missing.map((name) => `${name}:missing`),
];

return [{
  json: {
    ...x,
    agreement_gate: {
      policy_version: 'agreement-production-candidate-v0.2',
      mode: enforcementEnabled ? 'enforced' : 'shadow',
      evaluated_at: new Date().toISOString(),
      thresholds: {
        faithfulness_min: 0.90,
        hallucination_max: 0.10,
      },
      layers,
      score_completeness: codePresent && faithfulnessPresent && hallucinationPresent
        ? 'complete'
        : 'incomplete',
      would_release: wouldRelease,
      decision: wouldRelease ? 'agreement' : (failed.length ? 'disagreement' : 'insufficient_evidence'),
      reasons,
      release_action: enforcementEnabled
        ? (wouldRelease ? 'release' : 'hold_for_human_review')
        : 'continue_shadow_only',
      note: enforcementEnabled
        ? 'Enforced mode releases only after complete evaluator agreement.'
        : 'Candidate remains non-blocking until explicit owner approval.',
    },
    production_loop: {
      policy_version: 'production-loop-candidate-v0.1',
      enforcement_enabled: enforcementEnabled,
      release_authorized: releaseAuthorized,
      on_failure_when_enforced: 'hold_for_human_review',
      timeout_policy_when_enforced: 'fail_closed',
      rerun_scope: 'affected_stage_then_downstream_validation',
      promotion_requirement: 'explicit_owner_approval',
    },
  },
}];

const x=$input.first().json;
const previous=Number(x.evaluation_poll?.attempt??0);
const maxAttempts=18;
return [{json:{...x,evaluation_poll:{...(x.evaluation_poll??{}),attempt:previous+1,max_attempts:maxAttempts,interval_seconds:10,started_at:x.evaluation_poll?.started_at??new Date().toISOString(),status:'polling'}}}];

const response = $input.first().json;
const pollItems = $('Prepare Score Poll Attempt').all();
const original = pollItems[pollItems.length - 1].json;
const traceId = original.stage_trace_id || original.observability?.stage_trace_id || null;
const body = response.body ?? response;
const scores = Array.isArray(body.data) ? body.data : (Array.isArray(body) ? body : []);

const scoreName = (score) => score.name ?? score.scoreName ?? score.config?.name ?? null;
const scoreTraceId = (score) => score.traceId ?? score.trace_id ?? score.subject?.traceId ?? score.subject?.trace_id ?? null;
const scoreValue = (score) => {
  for (const key of ['value', 'numericValue', 'booleanValue', 'stringValue']) {
    if (score[key] !== undefined && score[key] !== null) return score[key];
  }
  return null;
};
const current = scores.filter((score) => !traceId || !scoreTraceId(score) || scoreTraceId(score) === traceId);
const find = (name) => current.find((score) => scoreName(score) === name);
const code = find('story_lf_code_evaluation_pass');
const faithfulness = find('story_llm_faithfulness') ?? find('llm_faithfulness');
const hallucination = find('story_llm_hallucination') ?? find('llm_hallucination');

return [{ json: {
  ...original,
  evaluation_scores: {
    langfuse_code: code ? scoreValue(code) : null,
    llm_faithfulness: faithfulness ? scoreValue(faithfulness) : null,
    llm_hallucination: hallucination ? scoreValue(hallucination) : null,
  },
  evaluation_poll: {
    ...(original.evaluation_poll ?? {}),
    score_complete: Boolean(code && faithfulness && hallucination),
    observed_required_scores: [code, faithfulness, hallucination].filter(Boolean).length,
    last_checked_at: new Date().toISOString(),
  },
  evaluation_score_evidence: {
    source: 'Langfuse Scores API v3',
    trace_id: traceId,
    retrieved_at: new Date().toISOString(),
    current_run_correlation: true,
    http_status: response.statusCode ?? null,
    raw_score_count: scores.length,
    correlated_score_count: current.length,
    required_score_names: [
      'story_lf_code_evaluation_pass',
      'llm_faithfulness (consolidated; story_llm_faithfulness accepted)',
      'llm_hallucination (consolidated; story_llm_hallucination accepted)',
    ],
    observed_score_names: current.map(scoreName).filter(Boolean),
  },
} }];

const x = $input.first().json;
if (x.production_loop?.release_authorized === true) return [];
const failed = Object.entries(x.agreement_gate?.layers ?? {}).filter(([, layer]) => layer.status !== 'pass').map(([name, layer]) => ({ layer: name, status: layer.status }));
return [{ json: { ...x, production_loop: { ...x.production_loop, route: 'hold_for_human_review', hold_status: 'awaiting_human_review', failed_layers: failed, correction_policy: 'record approved correction and rerun affected stage plus downstream validation', release_blocked: true } } }];

const x = $input.first().json;
const seconds = 45;
await new Promise((resolve) => setTimeout(resolve, seconds * 1000));
return [{ json: { ...x, evaluation_poll: { ...(x.evaluation_poll ?? {}), interval_seconds: seconds, strategy: 'single_delayed_check' } } }];

const x = $input.first().json;
const attempt = Number(x.evaluation_poll?.attempt ?? 0);
const maxAttempts = Number(x.evaluation_poll?.max_attempts ?? 6);
if (x.evaluation_poll?.score_complete === true || attempt >= maxAttempts) return [];
return [{ json: x }];
